import SwiftUI
import Charts

struct HealthView: View {
    @EnvironmentObject var vm: AppViewModel
    var body: some View {
        Nav { ScrollView { VStack(alignment: .leading, spacing: 18) { header; snapshotGrid; chart; dataInfo }.padding() }.background(Theme.background.ignoresSafeArea()).navigationTitle("Здоровье").toolbar { ToolbarItem(placement: .navigationBarTrailing) { Button { Task { await vm.refreshHealth() } } label: { Image(systemName: "arrow.clockwise") }.disabled(vm.isLoading) } }.overlay { if vm.isLoading { ProgressView() } } }
    }
    private var header: some View { Card { HStack { Image(systemName: vm.usingDemoData ? "iphone.gen3" : "heart.text.square.fill").font(.title2).foregroundStyle(Theme.mint); VStack(alignment: .leading) { Text(vm.usingDemoData ? "Демо-режим" : "Apple Health подключён").font(.headline); Text("Данные используются только для твоей личной динамики.").font(.caption).foregroundStyle(.secondary) }; Spacer() } } }
    private var snapshotGrid: some View { LazyVGrid(columns: [GridItem(.flexible()), GridItem(.flexible())], spacing: 12) { HealthValueCard(title: "Сон, среднее", value: vm.sleepAverageText, icon: "moon.zzz.fill"); HealthValueCard(title: "Шаги", value: vm.healthSnapshot.latestSteps.map { "\(Int($0))" } ?? "—", icon: "figure.walk"); HealthValueCard(title: "Пульс", value: vm.healthSnapshot.latestHeartRate.map { "\(Int($0))" } ?? "—", icon: "heart.fill"); HealthValueCard(title: "HRV", value: vm.healthSnapshot.latestHRV.map { "\(Int($0)) мс" } ?? "—", icon: "waveform.path.ecg"); HealthValueCard(title: "Ккал", value: vm.healthSnapshot.latestActiveEnergy.map { "\(Int($0))" } ?? "—", icon: "flame.fill"); HealthValueCard(title: "Дистанция", value: vm.healthSnapshot.latestDistanceKm.map { String(format: "%.1f км", $0) } ?? "—", icon: "location.fill"); HealthValueCard(title: "Тренировки", value: vm.healthSnapshot.latestWorkoutMinutes.map { "\(Int($0)) мин" } ?? "—", icon: "figure.run") } }
    private var chart: some View { Card { VStack(alignment: .leading, spacing: 10) { Text("Шаги за 30 дней").font(.headline); if vm.healthHistory.contains(where: { $0.steps != nil }) { Chart(vm.healthHistory) { day in if let steps = day.steps { LineMark(x: .value("Дата", day.date), y: .value("Шаги", steps)).interpolationMethod(.catmullRom); AreaMark(x: .value("Дата", day.date), y: .value("Шаги", steps)).opacity(0.08) } }.frame(height: 190) } else { VStack(spacing: 8) { Image(systemName: "chart.xyaxis.line").font(.title); Text("История пока недоступна").font(.headline); Text("Разреши доступ к шагам в приложении «Здоровье».").font(.caption).foregroundStyle(.secondary) }.frame(maxWidth: .infinity).frame(height: 170) } } } }
    private var dataInfo: some View { Card { VStack(alignment: .leading, spacing: 8) { Text("Показатели").font(.headline); Text("Сон • шаги • пульс покоя • тренировки • калории • дистанция • этажи • HRV • дыхание • вес").font(.footnote).foregroundStyle(.secondary); if let date = vm.healthSnapshot.updatedAt { Text("Обновлено \(date.formatted(date: .abbreviated, time: .shortened))").font(.caption).foregroundStyle(.secondary) } } } }
}

private struct HealthValueCard: View { let title: String; let value: String; let icon: String; var body: some View { Card { VStack(alignment: .leading, spacing: 7) { Label(title, systemImage: icon).font(.caption).foregroundStyle(.secondary); Text(value).font(.system(.title3, design: .rounded).weight(.bold)) } } } }
